  // scenario walls
  const wantOnly = (st.onlyWallSpecs ?? []).filter(w => w.only.includes(scn)).map(w => w.key).sort();
  const haveOnly = sc.walls.filter(w => pgOf(w).st === st.id && pgOf(w).only).map(w => pgOf(w).key).sort();
  ok(`${label}: scenario walls ${JSON.stringify(wantOnly)}`, JSON.stringify(wantOnly) === JSON.stringify(haveOnly), { have: haveOnly });
  const haveOD = sc.drawings.filter(d => pgOf(d).st === st.id && pgOf(d).only).length;
  ok(`${label}: scenario wall drawings (${wantOnly.length})`, haveOD === wantOnly.length, haveOD);
  const wantReg = st.regionSpecs.filter(r => !r.only || r.only.includes(scn)).map(r => r.key).sort();
  const haveReg = sc.regions.filter(r => pgOf(r).st === st.id).map(r => pgOf(r).key).sort();
  ok(`${label}: regions ${JSON.stringify(wantReg)}`, JSON.stringify(wantReg) === JSON.stringify(haveReg), { have: haveReg });
