const globalState = (mode, label) => {
  ok(`${label}: token vision ${mode === "sight" ? "on" : "off"}`, sc.tokenVision === (mode === "sight"), sc.tokenVision);
  ok(`${label}: fog exploration ${mode === "sight" ? "on" : "off"}`, (sc.fog.mode === 1) === (mode === "sight") && (mode === "sight" || sc.fog.mode === 0), sc.fog.mode);
  ok(`${label}: no combat on the scene`, game.combats.filter(c => c.scene?.id === sc.id).length === 0);
};

// ================================================================ STATIC
if (phase === "static" || phase === "all") {
  const r0 = await runReset({ mode: "paths", station: "all", scenario: "default" });
  ok("start: reset paths/all/default ran", r0.ok, r0.error ?? r0.notes);
  ok("scene: exactly one scene named ZZ Playground", game.scenes.filter(s => s.name === "ZZ Playground").length === 1);
  ok("scene: 100x100 squares (10000x10000 px)", sc.dimensions?.sceneWidth === 10000 || (sc.width === 10000 && sc.height === 10000), [sc.width, sc.height]);
  ok("scene: grid 100 px, padding 0", sc.grid.size === 100 && sc.padding === 0, [sc.grid.size, sc.padding]);
  ok("scene: no background image, light background colour", !sc.background?.src && !sc.levels.contents[0]?.background?.src && (() => { const c = Color.from(sc.levels.contents[0].background.color); return (0.3 * c.r + 0.59 * c.g + 0.11 * c.b) > 0.7; })(), [sc.background?.src, sc.levels.contents[0]?.background?.color]);
  ok("scene: global light on, darkness 0", sc.environment.globalLight.enabled === true && sc.environment.darknessLevel === 0);
  ok("scene: not the active scene", game.scenes.active?.id !== sc.id, game.scenes.active?.name);
  ok("scene: 16 stations in the data", V.stations.length === 16);
  res.measured.sceneId = sc.id;
  const tot = { walls: 0, tokens: 0, doors: 0, regions: 0 };
  for (const st of V.stations) {
    const walls = sc.walls.filter(w => pgOf(w).st === st.id && !pgOf(w).only);
    const doors = walls.filter(w => w.door);
    const regs = sc.regions.filter(r => pgOf(r).st === st.id);
    const toks = sc.tokens.filter(t => pgOf(t).st === st.id);
    const wantReg = st.regionSpecs.filter(r => !r.only).length;
    ok(`${st.id} ${st.name}: ${st.walls} walls, ${st.doors} doors, ${wantReg} regions, ${st.tokens} tokens`,
      walls.length === st.walls && doors.length === st.doors && regs.length === wantReg && toks.length === st.tokens,
      { walls: walls.length, doors: doors.length, regions: regs.length, tokens: toks.length });
    tot.walls += walls.length; tot.tokens += toks.length; tot.doors += doors.length; tot.regions += regs.length;
    // everything of the station lies inside its area
    const [ax0, ay0, ax1, ay1] = st.area;
    const out = walls.filter(w => w.c.some((v, i) => (i % 2 === 0 ? (v < ax0 - 1 || v > ax1 + 1) : (v < ay0 - 1 || v > ay1 + 1)))).length
      + toks.filter(t => t.x < ax0 - 1 || t.y < ay0 - 1 || t.x + t.width * 100 > ax1 + 101 || t.y + t.height * 100 > ay1 + 101).length;
    ok(`${st.id}: walls and tokens inside the station's 24x24 area`, out === 0, out);
  }
  res.measured.totals = tot;
  ok("tokens: names carry the station and are always displayed, rotation locked", sc.tokens.every(t => /^S\d\d /.test(t.name) && t.displayName === 50 && t.lockRotation === true));
  ok("tokens: hero tokens are linked, everything else unlinked", sc.tokens.every(t => { const spec = V.stations.flatMap(s => s.tokenSpecs).find(x => x.name === pgOf(t).name); return spec && t.actorLink === !!spec.linked; }));
  ok("tokens: owners (A: Hero 1-4/Large/Huge/Slow/Fast; B: Hero 5-8/Horse/Rider)", sc.tokens.every(t => {
    const spec = V.stations.flatMap(s => s.tokenSpecs).find(x => x.name === pgOf(t).name);
    if (!spec.owner) return t.actor.ownership["zzPlayer0000008A"] !== 3 && t.actor.ownership["zzPlayer0000008B"] !== 3;
    return t.actor.ownership[spec.owner === "A" ? "zzPlayer0000008A" : "zzPlayer0000008B"] === 3;
  }));
  // every wall is also drawn: each wall's midpoint lies on a drawn line; every station has its label
  { const dsegs = [];
    for (const d of sc.drawings) { const p = d.shape?.points; if (d.shape?.type !== "p" || !p?.length || d.fillType !== 0) continue; for (let i = 0; i + 3 < p.length; i += 2) dsegs.push([d.x + p[i], d.y + p[i + 1], d.x + p[i + 2], d.y + p[i + 3]]); }
    const pd = (px_, py_, s) => { const [x0, y0, x1, y1] = s, dx = x1 - x0, dy = y1 - y0, l2 = dx * dx + dy * dy; let t = l2 ? ((px_ - x0) * dx + (py_ - y0) * dy) / l2 : 0; t = Math.max(0, Math.min(1, t)); return Math.hypot(px_ - (x0 + t * dx), py_ - (y0 + t * dy)); };
    const undrawn = sc.walls.filter(w => !pgOf(w).only).filter(w => { const mx = (w.c[0] + w.c[2]) / 2, my = (w.c[1] + w.c[3]) / 2; return !dsegs.some(s => pd(mx, my, s) <= 8); });
    ok(`walls: every wall (${sc.walls.filter(w => !pgOf(w).only).length}) is also drawn`, undrawn.length === 0, undrawn.slice(0, 5).map(w => [pgOf(w).st, w.c]));
    for (const st of V.stations) {
      const lab = sc.drawings.filter(d => pgOf(d).st === st.id && d.text);
      ok(`${st.id}: label "${st.id} - ${st.name}" and its instruction are drawn`, lab.some(d => d.text.startsWith(st.id + " ")) && lab.some(d => d.text === st.instruction), lab.map(d => d.text.slice(0, 30)));
    }
  }
  // measured widths (from the wall geometry)
  const segsOf = g => sc.walls.filter(w => pgOf(w).grp === g).map(w => w.c);
  for (const st of V.stations) for (const [k, m] of Object.entries(st.measure ?? {})) {
    const A = segsOf(m.groups[0]), B = segsOf(m.groups[1]);
    let min = Infinity; for (const a of A) for (const b of B) min = Math.min(min, segDist(a, b));
    const w = Math.round(min) / 100;     // px -> squares
    const wsq = min / 100;
    res.measured[`${st.id}.${k}`] = Math.round(wsq * 1000) / 1000;
    ok(`${st.id} ${k}: narrowest width ${m.width.toFixed(2)} +/- ${m.tol} square (${m.note}), measured ${wsq.toFixed(3)}`, A.length > 0 && B.length > 0 && Math.abs(wsq - m.width) <= m.tol, { A: A.length, B: B.length, wsq });
  }
  // the C stair: segments of 10 degrees or less
  const stairSegs = [...segsOf("S05.stair.in"), ...segsOf("S05.stair.out")];
  let maxTurn = 0;
  { const [ox, oy] = stById.S05.area, cx = ox + 1000, cy = oy + 1350;      // the circle the C is drawn on (10, 13.5 squares)
    for (const c of stairSegs) { const a1 = Math.atan2(c[1] - cy, c[0] - cx), a2 = Math.atan2(c[3] - cy, c[2] - cx); let d = Math.abs(a2 - a1); if (d > Math.PI) d = 2 * Math.PI - d; maxTurn = Math.max(maxTurn, d * 180 / Math.PI); } }
  res.measured.stairMaxSegmentTurnDeg = Math.round(maxTurn * 10) / 10;
  ok("S05: the stair's two walls are curved off-grid segments turning 10 degrees or less each", stairSegs.length >= 40 && maxTurn <= 10.01, { n: stairSegs.length, maxTurn });
  const stairFreeCells = (() => { // whole grid squares that lie fully between the two walls (a few only)
    const st = stById.S05, [ox, oy] = st.area, cx = ox + 1000, cy = oy + 1350; let n = 0;
    const inner = segsOf("S05.stair.in"), outer = segsOf("S05.stair.out");
    for (let gx = 10; gx < 17; gx++) for (let gy = 6; gy < 21; gy++) {
      const r = [ox + gx * 100 + 4, oy + gy * 100 + 4, ox + gx * 100 + 96, oy + gy * 100 + 96];
      const hitsWall = [...inner, ...outer].some(c => segHitsRect(c, r));
      const mid = [ox + gx * 100 + 50, oy + gy * 100 + 50]; const rr = Math.hypot(mid[0] - cx, mid[1] - cy);
      if (!hitsWall && mid[0] > cx && rr > 500 && rr < 700) n++;
    }
    return n;
  })();
  res.measured.stairWholeSquares = stairFreeCells;
  ok("S05: only a few whole squares fit inside the stair (<= 4)", stairFreeCells <= 4, stairFreeCells);
  // data integrity of the stations list (names of scenarios the reset knows)
  ok("stations.json scenarios all known to reset.js", V.stations.every(s => Object.keys(s.scenarios).every(n => typeof n === "string")));
}

// ================================================================ RESETS
if (phase === "resets" || phase === "all") {
  const S1 = stById.S01, S7 = stById.S07, S11 = stById.S11, S2 = stById.S02;
  // perturb the world the way a test session would
  const hero1 = sc.tokens.find(t => pgOf(t).name === "S01 Hero 1");
  await hero1.update({ x: hero1.x + 400, y: hero1.y + 300 }, { teleport: true, animate: false });
  const closed = sc.walls.find(w => pgOf(w).st === "S07" && pgOf(w).key === "closed");
  await closed.update({ ds: 1 });
  const hid = sc.tokens.find(t => pgOf(t).name === "S02 Hidden"); await hid.update({ hidden: false });
  const stray1 = (await sc.createEmbeddedDocuments("Token", [{ ...sc.tokens.find(t => pgOf(t).name === "S01 Monster 1").toObject(), _id: undefined, name: "STRAY flagged", x: S1.area[0] + 900, y: S1.area[1] + 900, flags: {} }]))[0];
  const stray2 = (await sc.createEmbeddedDocuments("Token", [{ ...sc.tokens.find(t => pgOf(t).name === "S01 Monster 1").toObject(), _id: undefined, name: "STRAY elsewhere", x: 9500, y: 9700, flags: {} }]))[0];
  const mud = sc.regions.find(r => pgOf(r).st === "S11"); if (mud) await mud.delete();
  const delWall = sc.walls.filter(w => pgOf(w).st === "S15" && pgOf(w).key === "door").map(w => w.id); if (delWall.length) await sc.deleteEmbeddedDocuments("Wall", delWall);
  const cmb = await Combat.create({ scene: sc.id, active: false }); await cmb.createEmbeddedDocuments("Combatant", [{ tokenId: hero1.id, actorId: hero1.actorId, sceneId: sc.id }]);
  try { hero1.object?.control?.({ releaseOthers: true }); } catch {}
  const rp = await runReset({ mode: "paths", station: "all", scenario: "default" });
  ok("reset paths: ran clean", rp.ok && !rp.notes.length, rp.error ?? rp.notes);
  globalState("paths", "reset paths");
  ok("reset paths: stray tokens removed (flagged-less ones, inside and outside a station)", !sc.tokens.some(t => /STRAY/.test(t.name)) && sc.tokens.size === V.stations.reduce((n, s) => n + s.tokens, 0), sc.tokens.size);
  ok("reset paths: a moved token is back on its start square", (() => { const t = sc.tokens.find(t => pgOf(t).name === "S01 Hero 1"); const [x, y] = specPos(S1, S1.tokenSpecs.find(s => s.name === "S01 Hero 1"), "default"); return near(t.x, x) && near(t.y, y); })());
  ok("reset paths: the hidden token is hidden again", sc.tokens.find(t => pgOf(t).name === "S02 Hidden").hidden === true);
  ok("reset paths: a door opened by hand is closed again, a deleted door and a deleted region are back", sc.walls.find(w => pgOf(w).st === "S07" && pgOf(w).key === "closed").ds === 0 && sc.walls.some(w => pgOf(w).st === "S15" && pgOf(w).key === "door") && sc.regions.some(r => pgOf(r).st === "S11"));
  ok("reset paths: selections released on this page", (canvas.tokens?.controlled?.length ?? 0) === 0);
  ok("reset paths: movement history empty", sc.tokens.every(t => !(t.movementHistory?.length)));
  ok("reset paths: sight on the hero tokens only (vision itself off)", sc.tokens.every(t => t.sight.enabled === !!V.stations.flatMap(s => s.tokenSpecs).find(x => x.name === pgOf(t).name).hero));
  for (const st of V.stations) checkStation(st, "default", `reset paths ${st.id}`);
  // sight
  const rs = await runReset({ mode: "sight", station: "all", scenario: "default" });
  ok("reset sight: ran clean", rs.ok && !rs.notes.length, rs.error ?? rs.notes);
  ok("reset sight: fog of war wiped (the reset call went out)", rs.fogReset === true, rs.notes);
  globalState("sight", "reset sight");
  const heroNames = new Set(V.stations.flatMap(s => s.tokenSpecs).filter(t => t.hero).map(t => t.name));
  const sightOn = sc.tokens.filter(t => t.sight.enabled).map(t => t.name);
  ok(`reset sight: sight enabled on the ${heroNames.size - 0} player-owned hero tokens only, on nothing else`, sightOn.length > 0 && sightOn.every(n => heroNames.has(pgOf(sc.tokens.getName(n)).name)) && [...heroNames].every(n => sightOn.includes(n)), { on: sightOn.length, heroes: heroNames.size, notHero: sightOn.filter(n => !heroNames.has(n)) });
  ok("reset sight: monsters, villagers, targets have no sight", sc.tokens.filter(t => !heroNames.has(pgOf(t).name)).every(t => !t.sight.enabled));
  for (const st of V.stations) checkStation(st, "default", `reset sight ${st.id}`);
  // station-scoped sight reset: only that station's heroes see
  const rs8 = await runReset({ mode: "sight", station: "S08", scenario: "default" });
  ok("reset sight S08: ran clean", rs8.ok, rs8.error ?? rs8.notes);
  ok("reset sight S08: only S08's heroes have sight", sc.tokens.filter(t => t.sight.enabled).every(t => pgOf(t).st === "S08") && sc.tokens.filter(t => t.sight.enabled).length === 2, sc.tokens.filter(t => t.sight.enabled).length);
  // back to paths
  const rb = await runReset({ mode: "paths", station: "all", scenario: "default" });
  ok("reset paths again: ran clean", rb.ok, rb.error ?? rb.notes);
  globalState("paths", "final paths");
  ok("reset paths again: sight on the hero tokens again", sc.tokens.filter(t => t.sight.enabled).length === heroNames.size);
  res.measured.resetMs = { paths: rp.ms, sight: rs.ms, pathsAgain: rb.ms };
}

// ================================================================ SCENARIOS
if (phase === "scenarios" || phase === "all") {
  const done = [];
  for (const st of V.stations) for (const scn of Object.keys(st.scenarios)) {
    if (scn === "default") continue;
    const r = await runReset({ mode: "paths", station: st.id, scenario: scn });
    ok(`${st.id} scenario ${scn}: set`, r.ok, r.error ?? r.notes);
    checkStation(st, scn, `${st.id}/${scn}`);
    if (st.scenarios[scn].combat) {
      const cs = game.combats.filter(c => c.scene?.id === sc.id);
      const c = cs[0];
      ok(`${st.id}/${scn}: a combat is running with ${st.scenarios[scn].combat.tokens.length} combatants, round 1, ${st.scenarios[scn].combat.turn} to act`,
        cs.length === 1 && c.started && c.round === 1 && c.combatants.size === st.scenarios[scn].combat.tokens.length && c.combatant?.token?.name === st.scenarios[scn].combat.turn,
        { n: cs.length, started: c?.started, round: c?.round, size: c?.combatants.size, turn: c?.combatant?.token?.name });
    }
    const rd = await runReset({ mode: "paths", station: st.id, scenario: "default" });
    ok(`${st.id} scenario ${scn}: reset back to default`, rd.ok, rd.error ?? rd.notes);
    checkStation(st, "default", `${st.id}/${scn} -> default`);
    ok(`${st.id}/${scn} -> default: no combat left`, game.combats.filter(c => c.scene?.id === sc.id).length === 0);
    done.push(`${st.id}/${scn}`);
  }
  res.measured.scenariosRun = done;
  // one scene-wide scenario: every station that has it
  const ra = await runReset({ mode: "paths", station: "all", scenario: "back" });
  ok("station=all scenario=back: ran", ra.ok, ra.error ?? ra.notes);
  checkStation(stById.S03, "back", "all/back S03"); checkStation(stById.S04, "back", "all/back S04"); checkStation(stById.S01, "default", "all/back S01 (no such scenario: default)");
  const rz = await runReset({ mode: "paths", station: "all", scenario: "default" });
  ok("station=all default again", rz.ok, rz.error ?? rz.notes);
  for (const st of V.stations) checkStation(st, "default", `final ${st.id}`);
  globalState("paths", "final");
  // bad parameters are refused, change nothing
  const bad1 = await runReset({ mode: "paths", station: "S99", scenario: "default" });
  const bad2 = await runReset({ mode: "paths", station: "S03", scenario: "nope" });
  const bad3 = await runReset({ mode: "fog", station: "all", scenario: "default" });
  ok("bad station / scenario / mode are refused", !bad1.ok && !bad2.ok && !bad3.ok, [bad1.error, bad2.error, bad3.error]);
}

res.failed = res.checks.filter(c => !c.pass).length;
res.pass = res.failed === 0;
res.total = res.checks.length;
res.ms = Date.now() - t0;
return res;
